def diff_dicts(old, new):
    added = set(new) - set(old)
    removed = set(old) - set(new)
    changed = {k for k in set(old) & set(new) if old[k] != new[k]}
    return {'added': sorted(added), 'removed': sorted(removed), 'changed': sorted(changed)}

