import time

class TTLCache:
    def __init__(self, ttl=60.0):
        self.ttl = ttl
        self._data = {}

    def set(self, key, value):
        self._data[key] = (value, time.monotonic())

    def get(self, key, default=None):
        if key not in self._data:
            return default
        value, ts = self._data[key]
        if time.monotonic() - ts > self.ttl:
            del self._data[key]
            return default
        return value

